{"tool":"sandbox","code":"use std::fs;

fn main() {
    // Method A: trial division by previously found primes up to sqrt(n)
    let mut primes_a: Vec<u64> = Vec::new();
    let mut n: u64 = 2;
    while primes_a.len() < 200 {
        let sqrt_n = (n as f64).sqrt() as u64;
        let mut is_prime = true;
        for &p in primes_a.iter() {
            if p > sqrt_n {
                break;
            }
            if n % p == 0 {
                is_prime = false;
                break;
            }
        }
        if is_prime {
            primes_a.push(n);
        }
        n += 1;
    }

    // Method B: Sieve of Eratosthenes over 0..=2000
    let limit: usize = 2000;
    let mut sieve = vec![true; limit + 1];
    sieve[0] = false;
    sieve[1] = false;
    let mut i: usize = 2;
    while i * i <= limit {
        if sieve[i] {
            let mut j = i * i;
            while j <= limit {
                sieve[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    let all_b: Vec<u64> = (2..=limit as u64).filter(|&x| sieve[x as usize]).collect();
    assert!(
        all_b.len() >= 200,
        "sieve bound too small: only {} primes up to {}",
        all_b.len(),
        limit
    );
    let primes_b: Vec<u64> = all_b.into_iter().take(200).collect();

    // Cross-check the two independent methods
    assert_eq!(primes_a, primes_b, "Method A and Method B disagree");

    let count = primes_a.len();
    let sum: u64 = primes_a.iter().sum();
    let largest = primes_a[count - 1];

    assert_eq!(count, 200, "count mismatch");
    assert_eq!(largest, 1223, "largest mismatch");
    assert_eq!(sum, 111587, "sum mismatch");

    let first_primes: Vec<String> = primes_a.iter().take(5).map(|p| p.to_string()).collect();
    let last_primes: Vec<String> = primes_a[(count - 5)..].iter().map(|p| p.to_string()).collect();

    let json = format!(
        r#"{{"count":{},"sum":{},"largest":{},"check":"agree","first_primes":[{}],"last_primes":[{}]}}"#,
        count,
        sum,
        largest,
        first_primes.join(","),
        last_primes.join(",")
    );

    fs::create_dir_all("/work/artifacts").expect("failed to create /work/artifacts");
    fs::write("/work/artifacts/result.json", &json).expect("failed to write result.json");

    println!(
        "OK: count={} sum={} largest={} check=agree (trial division == sieve)",
        count, sum, largest
    );
    println!("wrote /work/artifacts/result.json: {}", json);
}","summary":"Run Rust program: first 200 primes via trial division and Sieve of Eratosthenes, cross-checked with assert_eq!, asserted count=200/sum=111587/largest=1223, wrote /work/artifacts/result.json"}

